// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  AdaptiveBatchLoader,
  BoundedCache,
  QueryFailure,
} from "../../../main/frontend/graph-explorer/request-batching.ts";
test("small concurrent requests coalesce, map by key, and share overlapping keys", async () => {
  const calls = [];
  const loader = new AdaptiveBatchLoader(
    async (keys) => {
      calls.push(keys);
      return {
        values: new Map(
          keys
            .slice()
            .reverse()
            .map((k) => [k, k.toUpperCase()]),
        ),
      };
    },
    { windowMs: 5 },
  );
  const [a, b] = await Promise.all([
    loader.loadMany(["a", "b"]),
    loader.loadMany(["b", "c"]),
  ]);
  assert.equal(calls.length, 1);
  assert.deepEqual(calls[0], ["a", "b", "c"]);
  assert.deepEqual(a, [
    ["a", "A"],
    ["b", "B"],
  ]);
  assert.deepEqual(b, [
    ["b", "B"],
    ["c", "C"],
  ]);
  loader.dispose();
});
test("adaptive splitting retries oversized batches without losing any keys", async () => {
  const calls = [];
  const loader = new AdaptiveBatchLoader(
    async (keys) => {
      calls.push(keys.length);
      if (keys.length > 2) throw new QueryFailure("too big", 413);
      return { values: new Map(keys.map((k) => [k, k])) };
    },
    { windowMs: 0, initialSize: 8 },
  );
  const result = await loader.loadMany(["a", "b", "c", "d", "e"]);
  assert.equal(result.length, 5);
  assert.ok(result.every(([k, v]) => k === v));
  assert.ok(calls.includes(5) && calls.includes(2));
  assert.ok(loader.stats.splits > 0);
  loader.dispose();
});
test("cancelling one consumer preserves a shared request and queued cancellations never fetch", async () => {
  let calls = 0;
  const loader = new AdaptiveBatchLoader(
    async (keys) => {
      calls++;
      return { values: new Map(keys.map((k) => [k, k])) };
    },
    { windowMs: 5 },
  );
  const controller = new AbortController();
  const a = loader.load("x", controller.signal);
  const b = loader.load("x");
  controller.abort();
  await assert.rejects(a, { name: "AbortError" });
  assert.equal(await b, "x");
  const c = new AbortController();
  const unused = loader.load("unused", c.signal);
  c.abort();
  await assert.rejects(unused, { name: "AbortError" });
  assert.equal(calls, 1);
  loader.dispose();
});
test("LRU expiry includes negative entries and enforces byte bounds", () => {
  let now = 0;
  const cache = new BoundedCache(2, 60, () => now);
  cache.set("missing", [], 20);
  assert.deepEqual(cache.get("missing"), []);
  now = 21;
  assert.equal(cache.get("missing"), undefined);
  cache.set("a", "a", 100);
  cache.set("b", "b", 100);
  cache.get("a");
  cache.set("c", "c", 100);
  assert.equal(cache.get("b"), undefined);
  cache.set("huge", "x".repeat(100), 100);
  assert.equal(cache.get("huge"), undefined);
});
test("an immediate replacement request survives cancellation of the previous active request", async () => {
  let started;
  const active = new Promise((resolve) => {
    started = resolve;
  });
  let calls = 0;
  const loader = new AdaptiveBatchLoader(
    async (keys, signal) => {
      calls++;
      if (calls === 1) {
        started();
        await new Promise((_, reject) =>
          signal.addEventListener(
            "abort",
            () =>
              setTimeout(
                () => reject(new DOMException("cancelled", "AbortError")),
                5,
              ),
            { once: true },
          ),
        );
      }
      return { values: new Map(keys.map((key) => [key, "fresh"])) };
    },
    { windowMs: 0 },
  );
  const controller = new AbortController();
  const old = loader.load("x", controller.signal);
  await active;
  controller.abort();
  const fresh = loader.load("x");
  await assert.rejects(old, { name: "AbortError" });
  assert.equal(await fresh, "fresh");
  assert.equal(calls, 2);
  loader.dispose();
});
